import json
from datetime import datetime

def to_json(doc):
    out = {}
    for key, value in doc.items():
        if isinstance(value, datetime):
            value = value.isoformat()
        out[key] = value
    out['id'] = str(out.pop('_id'))
    return out

doc = {'_id': 7, 'name': 'Ayşe', 'created_at': datetime(2026, 11, 2, 9, 30)}
print(json.dumps(to_json(doc), ensure_ascii=False))

def match(pattern, path):
    p_parts, parts = pattern.strip('/').split('/'), path.strip('/').split('/')
    if len(p_parts) != len(parts):
        return None
    params = {}
    for p, value in zip(p_parts, parts):
        if p.startswith('<'):
            params[p[1:-1]] = value
        elif p != value:
            return None
    return params

print(match('/students/<id>', '/students/5'), match('/students/<id>', '/teachers/5'))

