REQUIRED = ['name', 'country']

def validate(data):
    errors = []
    for field in REQUIRED:
        if not str(data.get(field, '')).strip():
            errors.append(f'{field} is required')
    if 'birthyear' in data and not str(data['birthyear']).isdigit():
        errors.append('birthyear must be a number')
    return errors

