routes = {'/students': {'GET': lambda: (200, ['Ece', 'Can']),
                        'POST': lambda: (201, 'created')}}

def dispatch(method, path):
    methods = routes.get(path)
    if methods is None:
        return 404, 'not found'
    if method not in methods:
        return 405, 'allowed: ' + ', '.join(methods)
    return methods[method]()

for method, path in [('GET', '/students'), ('DELETE', '/students'), ('GET', '/teachers')]:
    print(method, path, dispatch(method, path))

